mapper.select:
SELECT o.id as organizerId, o.username as organizerName, COUNT(DISTINCT a.id) as totalActivities, COUNT(DISTINCT CASE WHEN a.status = 4 THEN a.id END) as completedActivities, COUNT(DISTINCT CASE WHEN a.status = 3 THEN a.id END) as ongoingActivities, COUNT(DISTINCT ar.id) as totalRegistrations, COUNT(DISTINCT c.id) as checkinCount, COALESCE(SUM(c.actual_service_hours), 0) as totalServiceHours, COUNT(DISTINCT ar.user_id) as uniqueVolunteers, CASE WHEN COUNT(DISTINCT CASE WHEN ar.status = 2 THEN ar.id END) > 0 THEN ROUND(COUNT(DISTINCT c.id) * 100.0 / COUNT(DISTINCT CASE WHEN ar.status = 2 THEN ar.id END), 2) ELSE 0 END as avgCompletionRate FROM sys_user o LEFT JOIN activity a ON o.id = a.organizer_id AND a.deleted = 0
AND YEAR(a.start_time) = #{year}
LEFT JOIN activity_registration ar ON a.id = ar.activity_id AND ar.deleted = 0 LEFT JOIN activity_checkin c ON a.id = c.activity_id AND c.deleted = 0 WHERE o.deleted = 0 GROUP BY o.id, o.username HAVING totalActivities > 0 ORDER BY totalActivities DESC

SELECT ac.id as categoryId, ac.category_name as categoryName, ac.category_code as categoryCode, COUNT(DISTINCT a.id) as activityCount, COUNT(DISTINCT ar.id) as totalRegistrations, COUNT(DISTINCT c.id) as checkinCount, COALESCE(SUM(c.actual_service_hours), 0) as totalServiceHours, CASE WHEN COUNT(DISTINCT CASE WHEN ar.status = 2 THEN ar.id END) > 0 THEN ROUND(COUNT(DISTINCT c.id) * 100.0 / COUNT(DISTINCT CASE WHEN ar.status = 2 THEN ar.id END), 2) ELSE 0 END as completionRate FROM activity_category ac LEFT JOIN activity a ON ac.id = a.category_id AND a.deleted = 0
AND YEAR(a.start_time) = #{year}
LEFT JOIN activity_registration ar ON a.id = ar.activity_id AND ar.deleted = 0 LEFT JOIN activity_checkin c ON a.id = c.activity_id AND c.deleted = 0 WHERE ac.deleted = 0 GROUP BY ac.id, ac.category_name, ac.category_code HAVING activityCount > 0 ORDER BY activityCount DESC

SELECT ac.category_name as categoryName, COUNT(DISTINCT sr.id) as activityCount, COALESCE(SUM(sr.service_hours), 0) as totalHours FROM service_record sr JOIN activity a ON sr.activity_id = a.id AND a.deleted = 0 JOIN activity_category ac ON a.category_id = ac.id WHERE sr.user_id = #{userId} AND sr.deleted = 0 AND sr.status = 1
AND YEAR(sr.service_date) = #{year}
GROUP BY ac.id, ac.category_name ORDER BY totalHours DESC

SELECT DATE_FORMAT(sr.service_date, '%m') as month, COUNT(DISTINCT sr.id) as activityCount, COALESCE(SUM(sr.service_hours), 0) as totalHours FROM service_record sr WHERE sr.user_id = #{userId} AND sr.deleted = 0 AND sr.status = 1
AND YEAR(sr.service_date) = #{year}
GROUP BY DATE_FORMAT(sr.service_date, '%m') ORDER BY month
